package com.bank.hub;

import java.util.logging.Logger;

public class ProvinceCounter {

    private static final Logger log = Logger.getLogger(ProvinceCounter.class.getName());
    private int[] parent;
    private int[] rank;

    private int find(int x) {
        if (parent[x] != x) parent[x] = find(parent[x]);
        return parent[x];
    }

    private boolean union(int a, int b) {
        int ra = find(a), rb = find(b);
        if (ra == rb) return false;
        if (rank[ra] < rank[rb]) parent[ra] = rb;
        else if (rank[ra] > rank[rb]) parent[rb] = ra;
        else { parent[rb] = ra; rank[ra]++; }
        return true;
    }

    public int countProvinces(int[][] isConnected) {
        int n = isConnected.length;
        parent = new int[n];
        rank = new int[n];
        for (int i = 0; i < n; i++) parent[i] = i;
        int count = n;
        for (int i = 0; i < n; i++)
            for (int j = i + 1; j < n; j++)
                if (isConnected[i][j] == 1 && union(i, j)) {
                    count--;
                    final int c = count, fi = i, fj = j;
                    log.info(() -> "Hub " + fi + " joined hub " + fj + "; provinces=" + c);
                }
        final int result = count;
        log.info(() -> "Total provinces: " + result);
        return count;
    }
}
