package com.bank.hub;

import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

public class ProvinceDemo {

    private static final Logger log = Logger.getLogger(ProvinceDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        log.info("National Bank of India — Hub Province Counter");
        int[][] isConnected = {
            {1, 1, 0},
            {1, 1, 0},
            {0, 0, 1}
        };
        ProvinceCounter counter = new ProvinceCounter();
        int provinces = counter.countProvinces(isConnected); // expect 2
        log.info("Provinces = " + provinces);
    }
}
